module p2p_streaming ( input clk, input rst_n, input start, input [7:0] p_i [0:3], input [7:0] b_i [0:3], input [7:0] u_i [0:3], input [4:0] C, output reg [7:0] result, output reg done ); parameter IDLE = 3'd0, INIT=1, UPLOAD_CALC=2, VALIDATE=3, UPDATE_RESULT=4, INCREMENT=5, CHECK_BUFFER=6, DONE=7; reg [2:0] state, next_state; reg [15:0] current_B, max_B; reg [15:0] total_bandwidth, total_required; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; current_B <= -128; max_B <= -128; total_bandwidth <= 0; total_required <= 0; done <= 1'b0; end else begin state <= next_state; case (state) IDLE: begin next_state <= start ? INIT : IDLE; end INIT: begin total_bandwidth <= u_i[0] + u_i[1] + u_i[2] + u_i[3]; next_state <= UPLOAD_CALC; end UPLOAD_CALC: begin total_required <= 0; if (current_B + (C << 8) + (signed(p_i[0]) << 8) - (signed(b_i[0]) << 8) > 0) begin total_required <= total_required + current_B + (C << 8) + (signed(p_i[0]) << 8) - (signed(b_i[0]) << 8); end if (current_B + (C << 8) + (signed(p_i[1]) << 8) - (signed(b_i[1]) << 8) > 0) begin total_required <= total_required + current_B + (C << 8) + (signed(p_i[1]) << 8) - (signed(b_i[1]) << 8); end if (current_B + (C << 8) + (signed(p_i[2]) << 8) - (signed(b_i[2]) << 8) > 0) begin total_required <= total_required + current_B + (C << 8) + (signed(p_i[2]) << 8) - (signed(b_i[2]) << 8); end if (current_B + (C << 8) + (signed(p_i[3]) << 8) - (signed(b_i[3]) << 8) > 0) begin total_required <= total_required + current_B + (C << 8) + (signed(p_i[3]) << 8) - (signed(b_i[3]) << 8); end next_state <= VALIDATE; end VALIDATE: begin next_state <= UPDATE_RESULT; end UPDATE_RESULT: begin if (total_required <= (total_bandwidth << 8)) begin if (current_B > max_B) begin max_B <= current_B; end end next_state <= INCREMENT; end INCREMENT: begin current_B <= current_B + 1; next_state <= CHECK_BUFFER; end CHECK_BUFFER: begin if (current_B > 127) begin done <= 1'b1; next_state <= DONE; end else begin next_state <= UPLOAD_CALC; end end DONE: begin next_state <= DONE; end default: begin next_state <= IDLE; end endcase end end assign result = max_B[15:8]; endmodule